arguments.command:
python3 << 'EOF'
import parse

fmt = '''
            letters: {:w}
            non-letters: {:W}
            whitespace: "{:s}"
            non-whitespace: \t{:S}\n
            digits: {:d}
            non-digits: {:D}
            numbers with thousands: {:n}
            fixed-point: {:f}
            floating-point: {:e}
            general numbers: {:g} {:g}
            binary: {:b}
            octal: {:o}
            hex: {:x}
'''

p = parse.Parser(fmt)
print('Type conversions:')
for k, v in sorted(p._type_conversions.items()):
    print(f'  {k}: {v}')
print()
print('Fixed fields:', p._fixed_fields)
EOF
